#pragma GCC optimize("O3")
#pragma GCC target("sse4")

#include <bits/stdc++.h>

using namespace std;

typedef long long ll;
typedef long double ld;
typedef complex<ld> cd;

typedef pair<int, int> pi;
typedef pair<ll, ll> pl;
typedef pair<ld, ld> pd;

typedef vector<int> vi;
typedef vector<ld> vd;
typedef vector<ll> vl;
typedef vector<pi> vpi;
typedef vector<pl> vpl;
typedef vector<cd> vcd;

template <class T>
using pq = priority_queue<T>;
template <class T>
using pqg = priority_queue<T, vector<T>, greater<T>>;

#define foab(i, a, b) for (int i = a; i < (b); i++)
#define fora(i, a) for (int i = 0; i < (a); i++)
#define forabd(i, a, b) for (int i = (b)-1; i >= a; i--)
#define forad(i, a) for (int i = (a)-1; i >= 0; i--)
#define trav(a, x) for (auto &a : x)
#define uid(a, b) uniform_int_distribution<int>(a, b)(rng)

#define sz(x) (int)(x).size()
#define mp make_pair
#define pb push_back
#define f first
#define s second
#define lb lower_bound
#define ub upper_bound
#define all(x) x.begin(), x.end()
#define ins insert

template <class T>
bool ckmin(T &a, const T &b) {
  return b < a ? a = b, 1 : 0;
}
template <class T>
bool ckmax(T &a, const T &b) {
  return a < b ? a = b, 1 : 0;
}

mt19937 rng(chrono::steady_clock::now().time_since_epoch().count());

const int MOD = 1000000007;
const char nl = '\n';
const int MX = 100001;
// ll rec(int i, vl &a, vl &b, vl &c, ll k1, ll k2,
// vector<vector<vector<ll>>> &dp) {
// if (i < 0) return 0;
// ll froma = 0, fromb = 0, fromc = 0;
// if (dp[i][k1][k2] != -1) return dp[i][k1][k2];
// if (k1) {
// froma = a[i] + rec(i - 1, a, b, c, k1 - 1, k2, dp);
// }
// if (k2) {
// fromb = b[i] + rec(i - 1, a, b, c, k1, k2 - 1, dp);
// }
// fromc = c[i] + rec(i - 1, a, b, c, k1, k2, dp);
// return dp[i][k1][k2] = max(max(froma, fromb), fromc);
// }
void solve() {
  ll n;
  cin >> n;
  vl a, b, c;
  ll temp;
  fora(i, n) {
    cin >> temp;
    a.pb(temp);
  }
  fora(i, n) {
    cin >> temp;
    b.pb(temp);
  }

  fora(i, n) {
    cin >> temp;
    c.pb(temp);
  }
  ll k1, k2;
  cin >> k1 >> k2;
  ll t1 = k1;
  ll t2 = k2;
  k1++;
  k2++;
  vector<vector<vector<ll>>> dp(
      n, vector<vector<ll>>(n + 1, vector<ll>(n + 1, 0)));
  for (int i = 1; i <= n - 1; i++) {
    for (; k1 >= 1; k1--) {
      for (; k2 >= 1; k2--) {
        // cout << "i = " << i << "  k1 = " << k1 << " k2 =  " << k2 << endl;
        ll froma = 0, fromb = 0, fromc = 0;
        if (k1 > 1) {
          froma = a[i] + dp[i - 1][k1 - 1][k2];
        }
        if (k2 > 1) {
          fromb = b[i] + dp[i - 1][k1][k2 - 1];
        }
        fromc = c[i] + dp[i - 1][k1][k2];
        dp[i][k1][k2] = max(max(froma, fromb), fromc);
      }
    }
  }
  for (auto &it : dp) {
    for (auto &iit : it) {
      for (auto &iiit : iit) {
        cout << iiit << "  ";
      }
      cout << endl;
    }
    cout << endl;
  }
}
int main() {
  cin.tie(0)->sync_with_stdio(0);
  cin.exceptions(cin.failbit);
  int n, temp, q, x, y, z, t;
  cin >> t;
  while (t--) {
    solve();
  }
  return 0;
}

